import React, { useEffect, useMemo, useRef, useState } from "react";
import type { TaxClass, TaxFamily, TaxMechanism, TaxRep, TaxSummary, TaxVariant, TaxonomyJ } from "./types";
import { ASSETS } from "./App";

/** Generated by `python scripts/taxonomy_report.py` (viewer/public/taxonomy.json); one fetch per page load, shared. */
let TAX_CACHE: Promise<TaxonomyJ> | null = null;
export function loadTaxonomy(): Promise<TaxonomyJ> {
  if (!TAX_CACHE) {
    TAX_CACHE = fetch("./taxonomy.json").then((r) => { if (!r.ok) throw new Error(`taxonomy.json ${r.status}`); return r.json(); });
    TAX_CACHE.catch(() => { TAX_CACHE = null; });
  }
  return TAX_CACHE;
}
export function useTaxonomy(): { tax: TaxonomyJ | null; err: string | null } {
  const [tax, setTax] = useState<TaxonomyJ | null>(null);
  const [err, setErr] = useState<string | null>(null);
  useEffect(() => { let on = true; loadTaxonomy().then((t) => on && setTax(t)).catch((e) => on && setErr(String(e))); return () => { on = false; }; }, []);
  return { tax, err };
}

/** One colour per motion class (tree stripe, matrix row stripe, legend). */
export const CLASS_COLORS: Record<string, string> = {
  hinged_swing: "#e0a458", pivot: "#f2c57c", sliding: "#5bc0eb", folding: "#9bdeac", overhead: "#c084fc",
  rollup: "#f472b6", rotary: "#fb923c", hatch_flap: "#4ade80", flexible: "#a3e635",
};
const MECHS: { id: TaxMechanism; label: string }[] = [
  { id: "closer", label: "Closers" }, { id: "latch", label: "Latches" }, { id: "lock", label: "Locks" }, { id: "operator", label: "Operators" }, { id: "hinge", label: "Hinges" },
];
const FLAG_LABELS: Record<string, string> = {
  pair: "pair", dutch: "split leaf", both_ways: "double-acting", fold: "folding", accordion: "concertina", flap: "flap", strips: "strips",
  bi_parting: "bi-parting", center_opening: "centre-opening", breakout: "breakout", one_way: "one-way", self_closing: "self-closing",
  gravity_assisted_close: "gravity close", double_egress: "double egress", locked_until_credential: "credential", interlocked: "interlocked",
  auto_close: "auto-close", powered: "powered", unpowered_operator: "operator unpowered",
};
const KIN_SHORT: Record<string, string> = {
  hinge_vertical: "hinge ⟂", hinge_horizontal: "hinge ═", slide_horizontal: "slide ↔", slide_vertical: "lift ↕", rotor: "rotor ↻",
};

const nice = (s: string) => s.replace(/_/g, " ");
const rng = (lo: number, hi: number, d = 2) => Math.abs(hi - lo) < Math.pow(10, -d) ? lo.toFixed(d) : `${lo.toFixed(d)}–${hi.toFixed(d)}`;
function topKinds(d: Record<string, number>, n = 3): string[] {
  return Object.entries(d).filter(([k]) => k !== "none").slice(0, n).map(([k, v]) => `${nice(k)} ${v}`);
}
export function catalogueHref(filter: Record<string, string>): string {
  const p = new URLSearchParams(filter);
  return `#/?${p.toString()}`;
}
export function thumbHref(rep: TaxRep): string {
  return rep.thumb ? `${ASSETS}/doors/${rep.thumb}` : "";
}

/** Thumbnail strip: each image links to the door page. */
function Reps({ reps, size = 72 }: { reps: TaxRep[]; size?: number }) {
  return (
    <div className="hx-reps" role="list" aria-label="Representative doors">
      {reps.map((r) => (
        <a key={r.id} role="listitem" className="hx-rep" href={`#/door/${r.id}`} title={`${r.use_case} · ${r.id}${r.mass_kg != null ? ` · ${r.mass_kg.toFixed(0)} kg` : ""}`} style={{ width: size, height: Math.round(size * 0.75) }}>
          <img src={thumbHref(r)} loading="lazy" alt={r.use_case || r.id} width={size} height={Math.round(size * 0.75)} />
        </a>
      ))}
    </div>
  );
}

function Badges({ s, kin, showKin = true }: { s: TaxSummary; kin?: string; showKin?: boolean }) {
  const kinTypes = kin ? [kin] : Object.keys(s.kinematics);
  const leaves = Object.keys(s.leaves);
  const flags = Object.entries(s.flags).filter(([k, v]) => v >= Math.max(1, s.count * 0.3) && FLAG_LABELS[k]).map(([k]) => FLAG_LABELS[k]);
  return (
    <span className="hx-badges">
      {showKin && kinTypes.map((k) => <span key={k} className="chip kin" title={k}>{KIN_SHORT[k] ?? nice(k)}</span>)}
      {leaves.length > 0 && <span className="chip" title="leaves per door">{leaves.length === 1 ? `${leaves[0]} leaf${leaves[0] === "1" ? "" : "s"}` : `${leaves.join("/")} leaves`}</span>}
      {flags.map((f) => <span key={f} className="chip flag">{f}</span>)}
      {s.locked > 0 && <span className="chip" title={`${s.locked} start locked, ${s.locked_no_release} without a robot-side release`}>🔒 {s.locked}</span>}
      {s.signed_off < s.count && <span className="chip bad">{s.count - s.signed_off} need review</span>}
    </span>
  );
}

function Hardware({ s }: { s: TaxSummary }) {
  const rows: [string, string[]][] = [
    ["operators", topKinds(s.hardware.operator_kind, 4)], ["latches", topKinds(s.hardware.latch_kind, 3)],
    ["locks", topKinds(s.hardware.lock_kind, 3)], ["closers", topKinds(s.hardware.closer_kind, 3)], ["hinges", topKinds(s.hardware.hinge_kind, 3)],
  ];
  return (
    <div className="hx-hw">
      {rows.map(([k, v]) => <div key={k}><span className="k">{k}</span> {v.length ? v.map((x) => <span key={x} className="chip hw">{x}</span>) : <span className="chip none">none</span>}</div>)}
    </div>
  );
}

function Sizes({ s }: { s: TaxSummary }) {
  return <span className="hx-sizes">{rng(...s.sizes.leaf_width_m)} × {rng(...s.sizes.leaf_height_m)} m · {rng(...s.sizes.mass_kg, 0)} kg/leaf · difficulty {s.difficulty_mean.toFixed(1)}/5</span>;
}

function CountBar({ n, total, color }: { n: number; total: number; color: string }) {
  const pct = Math.max(0.5, (100 * n) / total);
  return <span className="hx-count" title={`${n} of ${total} doors`}><span className="bar" style={{ width: `${pct}%`, background: color }} /><span className="n">{n}</span></span>;
}

/** Native <details>/<summary>: keyboard accessible (Tab to focus, Enter/Space toggles), no JS needed for the toggle. */
function VariantNode({ v, fam, color, total }: { v: TaxVariant; fam: TaxFamily; color: string; total: number }) {
  return (
    <details className="hx-node variant" style={{ borderLeftColor: color }}>
      <summary>
        <span className="hx-title">{v.label} <code>{v.id}</code></span>
        <CountBar n={v.count} total={total} color={color} />
        <Badges s={v} showKin={Object.keys(v.kinematics).some((k) => k !== fam.kinematics_type)} />
      </summary>
      <div className="hx-body">
        {v.description && <p className="hx-desc">{v.description}{v.setting ? <span className="chip setting">{v.setting}</span> : null}</p>}
        <Sizes s={v} />
        <Hardware s={v} />
        <Reps reps={v.reps} size={64} />
        <a className="hx-browse" href={catalogueHref(v.filter)}>Browse {v.count} doors in the catalogue →</a>
      </div>
    </details>
  );
}

function FamilyNode({ f, color, total, open, highlight }: { f: TaxFamily; color: string; total: number; open: boolean; highlight: boolean }) {
  const ref = useRef<HTMLDetailsElement>(null);
  useEffect(() => { if (highlight && ref.current) { ref.current.open = true; ref.current.scrollIntoView({ block: "center" }); } }, [highlight]);
  return (
    <details className={"hx-node family" + (highlight ? " highlight" : "")} style={{ borderLeftColor: color }} open={open} ref={ref} id={`hx-${f.id}`}>
      <summary>
        <span className="hx-title">{f.label} <code>{f.id}</code></span>
        <CountBar n={f.count} total={total} color={color} />
        <Badges s={f} kin={f.kinematics_type} />
      </summary>
      <div className="hx-body">
        <p className="hx-desc">{f.description}</p>
        <div className="hx-facts">
          <div><span className="k">leaves</span> {f.leaves_note}</div>
          <div><span className="k">examples</span> {f.examples.join("; ")}</div>
          <div><span className="k">standards</span> {f.standards.join("; ")}</div>
          <div><span className="k">hard for a robot</span> {f.robot}</div>
        </div>
        <Sizes s={f} />
        <Hardware s={f} />
        <Reps reps={f.reps} />
        <div className="hx-links">
          <a className="hx-browse" href={catalogueHref({ family: f.id })}>Browse all {f.count} in the catalogue →</a>
          <a className="hx-browse" href="#/families">Flat list of door types</a>
        </div>
        <div className="hx-variants" role="group" aria-label={`${f.label} variants`}>
          <div className="hx-vhead">{f.variants.length} variant{f.variants.length === 1 ? "" : "s"} ({f.variant_rule === "context" ? "by context" : `by ${f.variant_rule}`})</div>
          {f.variants.map((v) => <VariantNode key={v.id} v={v} fam={f} color={color} total={f.count} />)}
        </div>
      </div>
    </details>
  );
}

function ClassNode({ c, total, open, highlightFamily }: { c: TaxClass; total: number; open: boolean; highlightFamily: string | null }) {
  const color = CLASS_COLORS[c.id] ?? "#888";
  return (
    <details className="hx-node class" style={{ borderLeftColor: color }} open={open || c.families.some((f) => f.id === highlightFamily)}>
      <summary>
        <span className="hx-title"><span className="hx-dot" style={{ background: color }} />{c.label}</span>
        <CountBar n={c.count} total={total} color={color} />
        <span className="hx-meta">{c.families.length} famil{c.families.length === 1 ? "y" : "ies"} · {c.families.reduce((a, f) => a + f.variants.length, 0)} variants</span>
        <Badges s={c} />
      </summary>
      <div className="hx-body">
        <p className="hx-desc">{c.description}</p>
        <Reps reps={c.reps} />
        <div className="hx-families">
          {c.families.map((f) => <FamilyNode key={f.id} f={f} color={color} total={c.count} open={open} highlight={f.id === highlightFamily} />)}
        </div>
      </div>
    </details>
  );
}

/** Families x mechanism-kind heat matrix (CSS grid; every cell is a button with a title, keyboard reachable). */
function Relations({ tax }: { tax: TaxonomyJ }) {
  const [mech, setMech] = useState<TaxMechanism>("closer");
  const [hover, setHover] = useState<{ r: number; c: number } | null>(null);
  const rel = tax.relations[mech];
  const famCount = useMemo(() => { const m: Record<string, number> = {}; for (const c of tax.motion_classes) for (const f of c.families) m[f.id] = f.count; return m; }, [tax]);
  const max = useMemo(() => Math.max(1, ...rel.matrix.flat()), [rel]);
  const colTotals = useMemo(() => rel.cols.map((_, j) => rel.matrix.reduce((a, row) => a + row[j], 0)), [rel]);
  const shared = tax.shared_mechanisms.filter((s) => s.mechanism === mech);
  const examples = tax.kind_examples[mech];
  return (
    <section className="hx-rel" aria-labelledby="hx-rel-title">
      <h2 id="hx-rel-title">Relationships: families × mechanism kinds</h2>
      <p className="hx-desc">Which families share the same closers, latches, locks, operators and hinges.  A cell is the number of doors of that family carrying that mechanism kind (a kind groups catalogue models: e.g. <i>surface overhead</i> = LCN 4040, Norton 1600, residential light …).  Darker = more doors; hover or focus a cell for details, click to open the family in the catalogue.</p>
      <div className="hx-tabs" role="tablist" aria-label="Mechanism">
        {MECHS.map((m) => <button key={m.id} role="tab" aria-selected={mech === m.id} className={"chip link" + (mech === m.id ? " active" : "")} onClick={() => setMech(m.id)}>{m.label} <span className="hx-meta">{tax.relations[m.id].cols.length}</span></button>)}
      </div>
      <div className="hx-matrix-wrap">
        <div className="hx-matrix" role="grid" aria-label={`Families by ${mech} kinds`} style={{ gridTemplateColumns: `minmax(150px, max-content) repeat(${rel.cols.length}, minmax(26px, 1fr))` }}>
          <div className="hx-corner" role="columnheader">family ╲ {mech} kind</div>
          {rel.cols.map((c, j) => (
            <div key={c} role="columnheader" className={"hx-col" + (hover?.c === j ? " hl" : "")} title={`${nice(c)}: ${colTotals[j]} doors · ${(examples[c] ?? []).join("; ")}`}><span>{nice(c)}</span></div>
          ))}
          {rel.rows.map((fam, i) => {
            const cls = tax.motion_class_of[fam];
            const color = CLASS_COLORS[cls] ?? "#888";
            return (
              <React.Fragment key={fam}>
                <div role="rowheader" className={"hx-row" + (hover?.r === i ? " hl" : "")} style={{ borderLeftColor: color }} title={`${tax.family_labels[fam]} · ${famCount[fam]} doors · ${cls}`}>
                  <a href={`#/hierarchy?family=${fam}`}>{tax.family_labels[fam] ?? fam}</a>
                </div>
                {rel.cols.map((c, j) => {
                  const n = rel.matrix[i][j];
                  const a = n ? 0.15 + 0.85 * Math.sqrt(n / max) : 0;
                  return (
                    <button key={c} role="gridcell" className={"hx-cell" + (n ? "" : " empty") + (hover && (hover.r === i || hover.c === j) ? " hl" : "")}
                      style={n ? { background: `rgba(224,164,88,${a.toFixed(3)})`, color: a > 0.55 ? "#111" : "var(--text)" } : undefined}
                      title={`${tax.family_labels[fam]} × ${nice(c)}: ${n} door${n === 1 ? "" : "s"}${famCount[fam] ? ` (${Math.round((100 * n) / famCount[fam])} % of the family)` : ""}`}
                      aria-label={`${tax.family_labels[fam]} ${nice(c)} ${n}`}
                      onMouseEnter={() => setHover({ r: i, c: j })} onMouseLeave={() => setHover(null)} onFocus={() => setHover({ r: i, c: j })} onBlur={() => setHover(null)}
                      onClick={() => { window.location.hash = catalogueHref({ family: fam }); }} disabled={!n}>
                      {n || ""}
                    </button>
                  );
                })}
              </React.Fragment>
            );
          })}
        </div>
      </div>
      <h3>Shared {mech} kinds</h3>
      <div className="hx-shared">
        {shared.length === 0 && <p className="hx-desc">No {mech} kind is shared by two or more families.</p>}
        {shared.map((s) => (
          <div key={s.kind} className="hx-shared-row">
            <span className="hx-shared-kind" title={(examples[s.kind] ?? []).join("; ")}>{nice(s.kind)} <span className="hx-meta">{s.n_doors} doors</span></span>
            <span className="hx-shared-fams">
              {s.families.map((f) => <a key={f} className="chip link" style={{ borderColor: CLASS_COLORS[tax.motion_class_of[f]] }} href={`#/hierarchy?family=${f}`}>{tax.family_labels[f] ?? f}</a>)}
            </span>
          </div>
        ))}
      </div>
    </section>
  );
}

export function Hierarchy({ query }: { query: string }) {
  const { tax, err } = useTaxonomy();
  const [expandAll, setExpandAll] = useState<boolean | null>(null);
  const params = new URLSearchParams(query);
  const highlightFamily = params.get("family");
  const [tab, setTab] = useState<"tree" | "relations">(params.get("view") === "relations" ? "relations" : "tree");
  useEffect(() => { if (highlightFamily) setTab("tree"); }, [highlightFamily]);
  if (err) return <div className="err">Could not load taxonomy.json: {err}. Run <code>python scripts/taxonomy_report.py</code>.</div>;
  if (!tax) return <div className="loading">Loading taxonomy…</div>;
  const nFam = tax.motion_classes.reduce((a, c) => a + c.families.length, 0);
  const nVar = tax.motion_classes.reduce((a, c) => a + c.families.reduce((b, f) => b + f.variants.length, 0), 0);
  return (
    <div className="hx">
      <div className="about" style={{ paddingBottom: 0 }}>
        <h1 style={{ margin: "8px 0" }}>Hierarchy</h1>
        <p style={{ color: "var(--muted)", marginTop: 0 }}>
          How the {tax.n_doors} doors are organised: <b>motion class</b> (how the leaf moves) → <b>family</b> (the {nFam} sampler families, also listed flat under <a href="#/families">Door types</a>) → <b>variant</b> ({nVar} real-world contexts or construction variants).
          Every door sits in exactly one leaf; counts add up to {tax.n_doors}.  Badges: kinematics type, leaves per door, mechanism flags, doors that start locked.
          Click a thumbnail for the 3D view, "Browse" for the catalogue filtered to that node.  Method and audit: <code>docs/TAXONOMY.md</code>.
        </p>
        <div className="stat-row" style={{ margin: "8px 0" }}>
          <div className="stat"><div className="n">{tax.motion_classes.length}</div><div className="l">motion classes</div></div>
          <div className="stat"><div className="n">{nFam}</div><div className="l">families</div></div>
          <div className="stat"><div className="n">{nVar}</div><div className="l">variants</div></div>
          <div className="stat"><div className="n">{tax.shared_mechanisms.length}</div><div className="l">mechanism kinds shared by ≥ 2 families</div></div>
          <div className="stat"><div className="n">{Object.keys(tax.kinematics_types).length}</div><div className="l">kinematics types</div></div>
        </div>
      </div>
      <div className="hx-toolbar" role="toolbar" aria-label="Hierarchy view">
        <div className="hx-tabs" role="tablist">
          <button role="tab" aria-selected={tab === "tree"} className={"chip link" + (tab === "tree" ? " active" : "")} onClick={() => setTab("tree")}>Tree</button>
          <button role="tab" aria-selected={tab === "relations"} className={"chip link" + (tab === "relations" ? " active" : "")} onClick={() => setTab("relations")}>Relationships</button>
        </div>
        {tab === "tree" && (
          <span className="hx-tools">
            <button onClick={() => setExpandAll(true)}>Expand all</button>
            <button onClick={() => setExpandAll(false)}>Collapse all</button>
          </span>
        )}
        <span className="hx-legend" aria-label="Motion class colours">
          {tax.motion_classes.map((c) => <span key={c.id} className="hx-legend-item"><span className="hx-dot" style={{ background: CLASS_COLORS[c.id] }} />{c.label} <span className="hx-meta">{c.count}</span></span>)}
        </span>
      </div>
      {tab === "tree" && (
        <div className="hx-tree" key={String(expandAll)} role="tree" aria-label="Door taxonomy">
          {tax.motion_classes.map((c) => <ClassNode key={c.id} c={c} total={tax.n_doors} open={expandAll === true || (expandAll === null && c.id === "hinged_swing" && !highlightFamily)} highlightFamily={highlightFamily} />)}
        </div>
      )}
      {tab === "relations" && <Relations tax={tax} />}
      <div className="hx-foot">taxonomy.json generated {tax.generated ?? "?"} from manifest {tax.manifest_generated ?? "?"} (seed {String(tax.seed)}) · <code>python scripts/taxonomy_report.py</code></div>
    </div>
  );
}
